  {"id":"nms-4","topic":"Neuroleptic Malignant Syndrome (NMS)","domain":"Internal medicine: emergency & acute care","discipline":"medicine","stem":"What is the primary pharmacologic trigger for NMS?","answer":"Dopamine receptor blockade by antidopaminergic agents (antipsychotics, antiemetics such as metoclopramide)","rationale":"Loss of hypothalamic dopaminergic inhibition disrupts thermoregulation; striatal blockade causes rigidity.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Neuroleptic Malignant Syndrome (NMS)","page":2}],"confusable_with":""},
